//! Completeness check (#42): every requested company, criterion and period
//! is answered or explicitly unknown. Requirements are generated by the
//! server from the intent; the model only claims a status per requirement,
//! and every claim is validated against the saved sources before it counts.
//! A requirement the model never addresses becomes `unknown`/`not_addressed`.
use crate::answer_blocks::{Completeness, CriterionKind, Fact, Requirement, RequirementClaim, RequirementStatus, UnknownReason};
use crate::parser::Intent;
use serde_json::Value;

/// A written period is expanded into at most this many years.
const MAX_PERIOD_YEARS: usize = 10;

/// One requirement per subject x capability x period (a requested year range
/// expanded per year), plus one per real `answer_operations` entry. `intent`
/// already excludes the synthetic operations the server adds later for the
/// model (the verbatim question and the empty-answer fallback), so no
/// separate filtering is needed here.
pub(crate) fn requirements(intent: &Intent) -> Vec<Requirement> {
    let mut out = Vec::new();
    let mut next_id = 1usize;
    let mut push = |out: &mut Vec<Requirement>, requirement: Requirement| {
        out.push(Requirement { id: format!("r{next_id}"), ..requirement });
        next_id += 1;
    };
    for goal in &intent.goals {
        let subject = intent.subjects.get(goal.subject);
        let subject_label = subject.map(|subject| subject.label.clone());
        let entity_ref = subject.and_then(|subject| subject.entity_ref).map(|entity_ref| entity_ref.to_string());
        let base = Requirement {
            id: String::new(), subject: Some(goal.subject), subject_label, entity_ref,
            criterion: goal.capability.clone(), criterion_kind: CriterionKind::Capability, period: None,
            status: RequirementStatus::Pending, reason: None, answered_by: Vec::new(), missing_ids: Vec::new(), evidence: Vec::new(),
        };
        let period_text = goal.constraints.get("period").and_then(Value::as_str);
        let years = period_text.map(requested_years).unwrap_or_default();
        if years.is_empty() {
            push(&mut out, base);
        } else {
            for year in years {
                push(&mut out, Requirement { period: Some(year), ..base.clone() });
            }
        }
    }
    for operation in &intent.answer_operations {
        push(&mut out, Requirement {
            id: String::new(), subject: None, subject_label: None, entity_ref: None, criterion: operation.clone(),
            criterion_kind: CriterionKind::Operation, period: None, status: RequirementStatus::Pending, reason: None,
            answered_by: Vec::new(), missing_ids: Vec::new(), evidence: Vec::new(),
        });
    }
    out
}

/// The distinct years named in a requested period, in order: an explicit two-
/// year range ("2015-2024", "2015 t/m 2024") expands to every year between,
/// capped at `MAX_PERIOD_YEARS`; otherwise every plausible year mentioned.
fn requested_years(text: &str) -> Vec<String> {
    let mut found: Vec<(usize, usize, u32)> = Vec::new();
    let bytes = text.as_bytes();
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index].is_ascii_digit() {
            let start = index;
            while index < bytes.len() && bytes[index].is_ascii_digit() { index += 1; }
            if index - start == 4 {
                if let Ok(year) = text[start..index].parse::<u32>() {
                    if (1900..=2100).contains(&year) { found.push((start, index, year)); }
                }
            }
        } else {
            index += 1;
        }
    }
    if let [(_, first_end, first), (second_start, _, second)] = found[..] {
        if is_range_separator(text[first_end..second_start].trim()) {
            let (low, high) = (first.min(second), first.max(second));
            if high - low < MAX_PERIOD_YEARS as u32 {
                return (low..=high).map(|year| year.to_string()).collect();
            }
        }
    }
    let mut years: Vec<u32> = found.into_iter().map(|(_, _, year)| year).collect();
    years.sort_unstable();
    years.dedup();
    years.truncate(MAX_PERIOD_YEARS);
    years.into_iter().map(|year| year.to_string()).collect()
}

fn is_range_separator(text: &str) -> bool {
    matches!(text, "-" | "\u{2013}" | "t/m" | "tot en met" | "to" | "through" | "until")
}

/// Applies the model's `requirement_status` claims to the server-generated
/// requirements and validates each one against the saved sources. A
/// requirement with no matching claim, or whose claim fails validation,
/// becomes `unknown` with an explicit reason; `complete` is true only when
/// every requirement is `answered` or `not_applicable`.
pub(crate) fn reconcile(requirements: Vec<Requirement>, claims: &[RequirementClaim], sources: &[Value]) -> Completeness {
    let requirements = requirements
        .into_iter()
        .map(|requirement| {
            let Some(claim) = claims.iter().find(|claim| claim.requirement_id == requirement.id) else {
                return unanswered(requirement, UnknownReason::NotAddressed);
            };
            let mut requirement = Requirement {
                status: claim.status, reason: claim.reason, answered_by: claim.answered_by.clone(),
                missing_ids: claim.missing_ids.clone(), evidence: claim.evidence.clone(), ..requirement
            };
            match requirement.status {
                RequirementStatus::Answered => {
                    if requirement.answered_by.is_empty() || requirement.evidence.is_empty() {
                        requirement = unanswered(requirement, UnknownReason::NotAddressed);
                    } else if !requirement.evidence.iter().all(|fact| resolves(fact, sources)) {
                        requirement = unanswered(requirement, UnknownReason::NotInSource);
                    } else if requirement.entity_ref.is_some() && !matches_entity(&requirement, sources) {
                        requirement = unanswered(requirement, UnknownReason::EntityMismatch);
                    } else if requirement.period.is_some() && !matches_period(&requirement) {
                        requirement = unanswered(requirement, UnknownReason::PeriodMismatch);
                    }
                }
                RequirementStatus::Unknown if requirement.reason.is_none() => requirement.reason = Some(UnknownReason::NotAddressed),
                RequirementStatus::NotApplicable if requirement.evidence.is_empty() => {
                    requirement = unanswered(requirement, UnknownReason::NotAddressed);
                }
                RequirementStatus::Unknown | RequirementStatus::NotApplicable | RequirementStatus::Pending => {}
            }
            requirement
        })
        .collect::<Vec<_>>();
    let complete = requirements.iter().all(|requirement| matches!(requirement.status, RequirementStatus::Answered | RequirementStatus::NotApplicable));
    Completeness { requirements, complete }
}

fn unanswered(requirement: Requirement, reason: UnknownReason) -> Requirement {
    Requirement { status: RequirementStatus::Unknown, reason: Some(reason), ..requirement }
}

/// The evidence pointer resolves to a scalar in the saved source, and the
/// claimed value (when the model supplied one) matches it.
fn resolves(fact: &Fact, sources: &[Value]) -> bool {
    let (Some(result_ref), Some(pointer)) = (fact.result_ref.as_deref(), fact.pointer.as_deref()) else { return false };
    if !crate::report_assets::evidence_pointer(pointer) { return false; }
    let Some(source) = sources.iter().find(|source| source["result_ref"].as_str() == Some(result_ref)) else { return false };
    let Some(resolved) = source["document"].pointer(pointer) else { return false };
    if !(resolved.is_string() || resolved.is_number() || resolved.is_boolean()) { return false; }
    fact.value.is_null() || semantically_equal(&fact.value, resolved)
}

fn semantically_equal(claimed: &Value, resolved: &Value) -> bool {
    match (claimed, resolved) {
        (Value::Number(a), Value::Number(b)) => (a.as_f64().unwrap_or(f64::NAN) - b.as_f64().unwrap_or(f64::NAN)).abs() < 1e-6,
        (Value::String(a), Value::String(b)) => a.trim().eq_ignore_ascii_case(b.trim()),
        (Value::String(a), _) => resolved.to_string().trim_matches('"') == a.trim(),
        _ => claimed == resolved,
    }
}

/// At least one cited fact comes from a document whose subject matches the
/// requirement's entity.
fn matches_entity(requirement: &Requirement, sources: &[Value]) -> bool {
    let Some(entity_ref) = requirement.entity_ref.as_deref() else { return true };
    requirement.evidence.iter().any(|fact| {
        fact.result_ref.as_deref()
            .and_then(|result_ref| sources.iter().find(|source| source["result_ref"].as_str() == Some(result_ref)))
            .is_some_and(|source| source["document"]["subject"]["entity_ref"].as_str() == Some(entity_ref))
    })
}

/// At least one cited fact carries the requirement's period, by key or
/// source text.
fn matches_period(requirement: &Requirement) -> bool {
    let Some(period) = requirement.period.as_deref() else { return true };
    requirement.evidence.iter().any(|fact| {
        fact.period.as_ref().is_some_and(|qualifier| {
            qualifier.value.as_deref() == Some(period) || qualifier.key.as_deref() == Some(period)
        })
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::answer_blocks::PeriodQualifier;
    use crate::parser::{Goal, Subject};
    use serde_json::json;
    use std::collections::BTreeMap;
    use uuid::Uuid;

    fn intent(period: &str) -> Intent {
        Intent {
            subjects: vec![Subject { entity_ref: Some(Uuid::nil()), label: "Acme".into(), values: BTreeMap::new() }],
            goals: vec![Goal { capability: "company.accounts".into(), subject: 0, constraints: BTreeMap::from([("period".into(), json!(period))]) }],
            answer_operations: vec!["Compare margins".into()],
            unresolved_references: vec![],
        }
    }

    #[test]
    fn a_year_range_expands_and_operations_get_their_own_requirement() {
        let reqs = requirements(&intent("2021 t/m 2023"));
        assert_eq!(reqs.iter().filter(|r| r.criterion_kind == CriterionKind::Capability).map(|r| r.period.clone().unwrap()).collect::<Vec<_>>(),
            ["2021", "2022", "2023"]);
        assert_eq!(reqs.last().unwrap().criterion, "Compare margins");
        assert_eq!(reqs.last().unwrap().criterion_kind, CriterionKind::Operation);
        assert!(reqs.iter().map(|r| &r.id).eq(["r1", "r2", "r3", "r4"].iter()));
    }

    #[test]
    fn an_unaddressed_requirement_becomes_not_addressed_and_incomplete() {
        let reqs = requirements(&intent("2022"));
        let completeness = reconcile(reqs, &[], &[]);
        assert!(!completeness.complete);
        assert!(completeness.requirements.iter().all(|r| r.status == RequirementStatus::Unknown && r.reason == Some(UnknownReason::NotAddressed)));
    }

    #[test]
    fn an_answered_claim_with_matching_entity_and_period_is_kept() {
        let mut plain = intent("2022");
        plain.answer_operations.clear();
        let reqs = requirements(&plain);
        let sources = vec![json!({"result_ref":"s1","document":{"subject":{"entity_ref":Uuid::nil().to_string()},"data":{"assets":100}}})];
        let claims = vec![RequirementClaim {
            requirement_id: "r1".into(), status: RequirementStatus::Answered, answered_by: vec!["o1".into()], reason: None,
            missing_ids: vec![], evidence: vec![Fact {
                result_ref: Some("s1".into()), pointer: Some("/data/assets".into()), value: json!(100),
                period: Some(PeriodQualifier { value: Some("2022".into()), ..Default::default() }), ..Default::default()
            }],
        }];
        let completeness = reconcile(reqs, &claims, &sources);
        assert!(completeness.complete);
        assert_eq!(completeness.requirements[0].status, RequirementStatus::Answered);
    }

    #[test]
    fn a_claim_for_the_wrong_entity_is_downgraded_to_unknown() {
        let reqs = requirements(&intent("2022"));
        let sources = vec![json!({"result_ref":"s1","document":{"subject":{"entity_ref":Uuid::new_v4().to_string()},"data":{"assets":100}}})];
        let claims = vec![RequirementClaim {
            requirement_id: "r1".into(), status: RequirementStatus::Answered, answered_by: vec!["o1".into()], reason: None,
            missing_ids: vec![], evidence: vec![Fact { result_ref: Some("s1".into()), pointer: Some("/data/assets".into()), value: json!(100), ..Default::default() }],
        }];
        let completeness = reconcile(reqs, &claims, &sources);
        assert!(!completeness.complete);
        assert_eq!(completeness.requirements[0].status, RequirementStatus::Unknown);
        assert_eq!(completeness.requirements[0].reason, Some(UnknownReason::EntityMismatch));
    }

    #[test]
    fn an_invented_pointer_is_never_taken_as_answered() {
        let reqs = requirements(&intent("2022"));
        let sources = vec![json!({"result_ref":"s1","document":{"data":{"assets":100}}})];
        let claims = vec![RequirementClaim {
            requirement_id: "r1".into(), status: RequirementStatus::Answered, answered_by: vec!["o1".into()], reason: None,
            missing_ids: vec![], evidence: vec![Fact { result_ref: Some("s1".into()), pointer: Some("/data/invented".into()), ..Default::default() }],
        }];
        let completeness = reconcile(reqs, &claims, &sources);
        assert_eq!(completeness.requirements[0].reason, Some(UnknownReason::NotInSource));
    }
}
